    # 籤
    @fortune_poems_json = [
      { title: "籤王 大吉", poem: "求得籤王百事良，萬事如意大吉昌；\n宜加力作行方便，可保福壽永安康。", explain: "萬事如意，大吉大利。宜多行善事、廣結善緣，可保長久富貴與身心安康。" },
      { title: "第一首 大吉籤", poem: "巍巍獨步向雲間，玉殿千官第一班。\n富貴榮華天付汝，福如東海壽如山。", explain: "平步青雲，位居顯貴，天賦富貴榮華，福壽齊全。問功名金榜題名，問婚姻幸福美滿，問疾病速癒。" },
      { title: "第二首 上吉籤", poem: "盈盈消息總天時，自此君當百事宜。\n若問前程歸縮地，更須方寸好修爲。", explain: "順應天時，百事亨通。前程光明，須修身積德。問功名有成，問婚姻圓滿，問訴訟宜和。" },
      { title: "第三首 中吉籤", poem: "衣食自然生處有，勸君不用苦勞心。\n但能孝悌存忠信，福祿來成禍不侵。", explain: "安份守己，直道而行，自然衣食無缺、福祿雙全。問婚姻遲成，問疾病痊癒，問訴訟宜和。" },
      { title: "第四首 下下籤", poem: "去年百事頗相宜，若較今年時運衰。\n好把瓣香告神佛，莫教福謝悔無追。", explain: "去年順遂，今年轉衰。宜及時祈神修福。問謀事難成，問財利無望，問婚姻阻礙多，問訴訟凶。" },
      { title: "第五首 中平籤", poem: "子有三般不自由，門庭蕭索冷如秋。\n若逢牛鼠交承日，萬事回春不用憂。", explain: "目前冷清不如意，年底（子丑月）自然回春。問財利待時，問婚姻謹慎，問功名有望，問疾病可癒。" },
      { title: "第六首 下下籤", poem: "何勞鼓瑟更吹笙，寸步如登萬里程。\n彼此懷疑不相信，休將私意憶濃情。", explain: "互信不足，貌合神離，徒勞無功。問婚姻無望，問合夥必敗，問訴訟宜和解。" },
      { title: "第七首 大吉籤", poem: "仙風道骨本天生，又遇仙宗爲主盟。\n指日丹成謝巖谷，一朝引領向天行。", explain: "天生貴格，得貴人神助，大富大貴者萬事如意。問仕途平步青雲，問財利亨通，問疾病遇名醫。" },
      { title: "第八首 上上籤", poem: "年來耕稼苦無收，今歲田疇定有秋。\n況遇太平無事日，士農工賈百無憂。", explain: "苦盡甘來，時來運轉，今年大豐收。問功名有希望，問財利漸入佳境，問婚姻感情轉好。" },
      { title: "第九首 大吉籤", poem: "望渠消息向長安，常把菱花仔細看。\n見說文書將八境，今朝喜色上眉端。", explain: "期待已久的好消息即將到來，喜上眉梢。問名利喜出望外，問婚姻有情人終成眷屬，問疾病短期康復（但財利恐有名無實）。" },
      { title: "第十首 下下籤", poem: "病患時時命寔衰，何須打瓦共鑽鑼。\n直教重見一陽復，始可求神仗佛持。", explain: "命運坎坷，疾病纏身。宜修身向善，等待冬至後轉運。問財利守舊勿妄動，問疾病冬至後有望，問訴訟宜和解。" },
      { title: "第十一首 下下籤", poem: "今年好事一番新，富貴榮華萃汝身。\n誰道機關難料處，到頭獨立轉傷神。", explain: "今年看似榮華，但世事無常，切勿執迷。宜謹慎守成。問功名不順，問財利守成，問婚姻慎重，問訴訟宜和。" },
      { title: "第十二首 中平籤", poem: "營爲期望在春前，誰料秋來又不然。\n直遇清江貫公子，一生活計始安全。", explain: "春天營謀順利，秋天卻遇阻礙。需待遠方貴人（或有力人士）相助，生活方能安定。問財利多不如意，問疾病調養至秋後可安，問訴訟大不利宜和解，問謀事單靠自己難成。" },
      { title: "第十三首 中平籤", poem: "君今庚甲未亨通，且向江頭作釣翁。\n玉兔重生應發跡，萬人頭上逞英雄。", explain: "目前時運未通（如姜太公釣魚），宜靜守待機。逢兔年/月/日或月圓時有發跡機會，可出人頭地。問功名晚成有望，問疾病拖延但終癒，問訴訟宜和，問行人稍阻但會歸。" },
      { title: "第十四首 下下籤", poem: "一見佳人便喜歡，誰知去後有多般。\n人情冷暖君休訝，歷涉應知行路難。", explain: "一見鍾情易，後續風波多。世態炎涼、人情冷暖正常，切勿衝動。問婚姻不可一時衝動，問名利不利，問疾病病情反覆，問行人歸期遙遠，問訴訟憂喜參半。" },
      { title: "第十五首 中平籤", poem: "兩家門戶各相當，不是婚姻莫較量。\n直待春風好消息，却請琴瑟向闌房。", explain: "僅論門當戶對而不問感情，婚姻難美滿。宜靜待春風（好緣分/時機），再議婚嫁。問婚姻慎重選擇，問功名寄望未來，問財利無大礙，防是非纏身。" },
      { title: "第十六首 下下籤", poem: "官事悠悠難辨明，不如息了且歸耕。\n傍人煽惑君休信，此事當謀親兄弟。", explain: "官司拖延難分是非，宜和解息訟回家安分。勿聽外人挑撥，應與親兄弟商量。問婚姻難成，問疾病拖延但需自信調養，問訴訟最忌繼續，宜尋親友共議。" },
      { title: "第十七首 下下籤", poem: "田園價貴好商量 事到公庭彼此傷 縱使機關圖得勝 定爲後世子孫殃", explain: "儘管田園買賣有糾紛，也要好好商量，彼此互相讓步，自可圓滿解決，何必意氣用事，對簿公堂，徒使兩敗俱傷呢？縱然使用計謀來勝訴，一樣會給後世子孫留下無窮禍患。" },
      { title: "第十八首 上吉籤", poem: "知君袖裏有驪珠，生不逢辰亦強圖。\n可歎頭顱已如許，而今方得貴人扶。", explain: "懷才不遇多年，如今終遇貴人提攜。雖晚但有轉機，宜把握。問謀事不可強求，修心向善可得助力，問功名/財運晚發，問疾病可癒。" },
      { title: "第十九首 上吉籤", poem: "嗟子從來未得時，今年星運頗相宜。\n營求動作都如意，和合中間定有期。", explain: "過去不得志，今年運勢大轉好。凡事營求順利，和合有期。問功名大有希望，問財利豐厚，問婚姻佳偶天成，問疾病漸癒。" },
      { title: "第二十首 下下籤", poem: "一生心事向誰論，今日才知誤我身。\n直到修身加積善，免教後患禍連門。", explain: "過去錯誤害了自己，宜徹底反省、修身積善，方能免禍。問謀事宜守舊，問財利恐虧，問訴訟有牢獄之虞，問婚姻多波折。" },
      { title: "第二十一首 中平籤", poem: "與君相約向江濱，魚雁頻傳信有真。\n若得明珠並美玉，從今萬事可無慮。", explain: "信用可靠，貴人訊息頻傳。若得良機（明珠美玉），從此無憂。問謀事有信用可成，問婚姻天賜良緣，問財利穩定，問行人歸期近。" }, 
      { title: "第二十二首 上吉籤", poem: "碧玉池中開白蓮，莊嚴色相自天然。\n雙飛萬里長江去，且待雲開月再圓。", explain: "純淨美好，如白蓮出水。目前小阻，終將圓滿雙飛。問婚姻美滿幸福，問功名金榜題名，問財利財源廣進，問疾病可癒。" },
      { title: "第二十三首 下下籤", poem: "花開花謝在春風，貴賤窮通百歲中。羨子榮華今已矣，到頭萬事總成空。", explain: "榮華富貴如過眼雲煙，盛極而衰是自然氣數。問名利曇花一現，問婚姻難成，問疾病恐變劇。" },
      { title: "第二十四首 中平籤", poem: "一春萬事苦憂煎，夏裏營求始帖然。更遇秋成冬至後，恰如騎鶴與腰纏。", explain: "先苦後甘，春天憂慮辛苦，夏秋冬季漸入佳境。問功名晚成，問婚姻中途有波折但終成。" },
      { title: "第二十五首 中平籤", poem: "寅午戌年多阻滯，卯子丑月漸亨嘉。更逢玉兔金雞會，柏木逢春自放花。", explain: "寅午戌年運勢多阻，冬末春初漸好，遇卯酉（兔雞）時機大發。宜靜待時機，不可強求。" },
      { title: "第二十六首 中吉籤", poem: "年來豐歉皆天數，自是今年旱較多。與子定期三日內，田疇霑足雨滂沱。", explain: "禍福天定，今年雖有小旱但神明庇佑，近期將有好轉。宜誠心祈求、樂善好施，自有感應。" },
      { title: "第二十七首 下下籤", poem: "世間萬物自有主，一粒一毫君莫取。英雄豪傑自天生，也須步步循規矩。", explain: "萬物各有其主，莫取不義之財。宜安分守己、循規蹈矩，否則將受天譴。問謀事先難，問婚姻難成。" },
      { title: "第二十八首 上吉籤", poem: "公侯將相本無種，好把勸勞契上天。火事盡從天理現，才高豈得困林泉。", explain: "勤苦奮鬥必得天賜福報，才幹之人終能脫困。問財利將轉好，問失物可尋，問疾病行善可癒。" },
      { title: "第二十九首 上上籤", poem: "祖宗積德幾多年，源遠流長慶自然。若更操修無倦已，天須還汝舊青氈。", explain: "祖先積德加上自身修持，自然榮華富貴。問功名高陞，問婚姻美滿，問疾病與訴訟皆吉。" },
      { title: "第三十首 中吉籤", poem: "奉公謹守莫欺心，自有亨通吉利臨。且下營求且休矣，秋期與子定佳音。", explain: "奉公守法、問心無愧，運勢自通。目前宜靜待，秋天后必有佳音。問謀事由難轉易，問疾病延醫可癒。" },
      { title: "第三十一首 中吉籤", poem: "秋冬作事只尋常，春到門庭漸音昌。千里信音符遠望，萱堂快樂未渠央。", explain: "秋冬運勢平平，春季開始興盛。遠方將傳來好消息。問功名來春有望，問財利宜平穩求進。" },
      { title: "第三十二首 下下籤", poem: "勞心泊泊竟何歸，疾病兼多是與非。事到頭來渾似夢，何如休要用心機。", explain: "為名利勾心鬥角，到頭來只換得疾病與是非。宜安分守成，莫費心機。問謀事多挫折，問疾病恐凶。" },
      { title: "第三十三首 中平籤", poem: "不分南北與西東，眼底昏昏耳似聾。熟讀訓庭經一卷，不論貴賤與窮通。", explain: "宜裝聾作啞，遠離是非，專心修身。莫管他人閒事以免惹禍。問疾病難癒，問訴訟宜避，問行人尚遠。" },
      { title: "第三十四首 中平籤", poem: "春夏纔過秋又冬，紛紛誤慮攬心胸。貴人垂手來相援，休把私心情意濃。", explain: "光陰似箭，雖有新計劃但力不從心。須心胸寬大、大公無私，方得貴人提拔援助，事業蒸蒸日上。" },
      { title: "第三十五首 下下籤", poem: "一山如畫對清江，門裏團圓事事雙。誰料半途分折去，空幃無語對銀缸。", explain: "好事成空，名成復敗。盛極而衰，中途恐有骨肉離散或人去樓空之憂。宜預作趨避之計。" },
      { title: "第三十六首 上吉籤", poem: "功名富貴自能爲，偶著仙鞭莫問伊。萬里鷗程君有分，吳山頂上好鑽龜。", explain: "富貴在於修持，不宜躁進。只要平時勤奮努力，時運一到必能前程遠大、名利雙收。" },
      { title: "第三十七首 中平籤", poem: "焚香來告復何辭，善惡平分汝自知。屏却昧公心裏事，出門無礙是通時。", explain: "善惡由心，天網恢恢。只要做人光明正大、屏除私心，出門做事自然亨通無阻。" },
      { title: "第三十八首 下下籤", poem: "蛩吟喞喞守孤幃，千里懸懸望信歸。等得榮華公子到，秋冬括括雨霏霏。", explain: "凶多吉少，希望經常落空如夢一場。問婚姻難圓滿，問疾病恐有不測，宜行善求神庇佑。" },
      { title: "第三十九首 下下籤", poem: "北山門下好安居，若問終時愼厥初。堪笑包藏許多事，鱗鴻雖便莫修書。", explain: "宜守成，不可輕舉妄動。做事須慎始，防範小人，且不可任意與人書信往來，以免招禍。" },
      { title: "第四十首 上吉籤", poem: "新來換得好規模，何用隨他步與趨。只聽耳邊消息到，崎嶇歷盡見亭衢。", explain: "應有主見，不宜盲從他人。只要創新並勤奮努力，歷盡艱難後必能迎頭趕上，獲得成就。" },
      { title: "第四十一首 中吉籤", poem: "自南自北自東西，欲到天涯誰作梯。遇國逢牛三弄笛，好將名姓榜頭題。", explain: "先難後易，須靠自己努力。遇子丑（牛鼠）年月日將有貴人扶助，金榜題名，富貴顯達。" },
      { title: "第四十二首 中吉籤", poem: "我曾許汝事和諧，誰料修爲汝自乖。但改新圖莫依舊，營謀應得稱心懷。", explain: "過而能改，善莫大焉。若覺運勢不佳，應改過遷善並更換舊有做法，自然萬事稱心遂意。" },
      { title: "第四十三首 中吉籤", poem: "一紙官書火急催，扁舟速下浪如雷。雖然目下多驚險，保汝平安去復回。", explain: "先凶後吉。雖目前處境驚險，但只要平日潔身自好、多積陰德，自有神明保佑化險為夷。" },
      { title: "第四十四首 中平籤", poem: "汝是人中最吉人，誤爲誤作損精神。堅牢一念酬香願，富貴榮華萃汝身。", explain: "本是有福之人，但因言行偏差耗神。若能謹言慎行、修身向善，富貴榮華指日可待。" },
      { title: "第四十五首 中平籤", poem: "好將心地力耕耘，彼此山頭總是墳；陰地不如心地好，修爲到底却輸君。", explain: "好好行善積德，無須外求好風水，求風水不如求心地好。只要遵守本分、修善積德，自然可得神明保佑。問財利宜守舊，問訴訟宜和解。" },
      { title: "第四十六首 中平籤", poem: "君是山中萬戶侯，信知騎馬勝騎牛；今朝馬上看山色，爭似騎牛得自由。", explain: "富貴人家雖好，但騎馬未必比騎牛自在。宜安分守己、寵辱不驚，方能享福。問財利宜守舊，問名利先難後易，需憑毅力克服險阻。" },
      { title: "第四十七首 下下籤", poem: "與君萬語復千言，祇欲平和雪爾寃；訟則終凶君記取，試於清夜把心捫。", explain: "千言萬語總歸一句：心平氣和可斷禍端。記取「訟則必凶」，平日行事須問心無愧。問婚姻雖有波折但終成，問訴訟大凶。" },
      { title: "第四十八首 中平籤", poem: "登山涉水正天寒，兄弟姻親那得安，幸遇虎頭人一喚，全家遂保汝重歡。", explain: "歷險艱難，幸遇貴人相助，終保全家平安。先難後易，憑毅力克服險阻，日後必功成名就。" },
      { title: "第四十九首 下下籤", poem: "彼此家居只一山，如何似隔鬼門關，日月如梭人易老，許多勞倦不如閒。", explain: "家不和謀事難成，彼此猜忌如隔鬼門關。與其勞碌一生無成，不如安分守閒。務必坦誠溝通，家和萬事興。" },
      { title: "第五十首 上平籤", poem: "人說今年勝舊年，也有步步與周旋，一家和氣多生福，勿非讒言莫聽偏。", explain: "今年運勢勝往年，仍須努力經營。家和萬事興，切勿聽信讒言偏聽。認清方向，把握原則，謀事可就。" },
      { title: "第五十一首 上吉籤", poem: "君今百事且隨緣，水到渠成聽自然，莫嘆年來不如意，喜逢新運稱心田。", explain: "百事隨緣，時機一到自然水到渠成。莫嘆過去不如意，否極泰來，新運將至，積極努力必有一番作為。" },
      { title: "第五十二首 上吉籤", poem: "兀坐幽居歡寂寥，孤燈掩映度消宵，萬金忽報秋光好，活計扁再渡北朝。", explain: "寒窗苦讀無人問，一舉成名天下知。時運已到，是施展抱負良機，當機立斷，定可功成名就。" },
      { title: "第五十三首 下下籤", poem: "艱難險阻路蹊蹺，南鳥孤飛依北巢，今日貴人曾識面，相逢卻在夏秋交。", explain: "一生歷盡坎坷，如南鳥孤飛。苦盡後終遇貴人，但須待夏末秋初方得提攜。凡事忍耐待機，訴訟宜和。" },
      { title: "第五十四首 中平籤", poem: "萬人叢裏逞英雄，便欲飛勝霄漢高，爭奈承流風未便，青燈黃卷且勤勞。", explain: "縱有沖天之志，奈何時運未到。仍須埋頭苦讀，充實自我，等待時機。目前功名無望，事業宜守舊。" },
      { title: "第五十五首 中平籤", poem: "勤耕力作莫蹉跎，衣食隨時安分過，縱使經商收倍利，不如逐歲廩禾多。", explain: "安分守己，腳踏實地勝過投機。勤耕力作，衣食無憂。經商雖有利，不如積存穀物穩當。" },
      { title: "第五十六首 下下籤", poem: "心頭理曲強詞遮，直欲欺官行賂斜，一旦醜形臨月鏡，身役憲網莫咨嗟。", explain: "理虧強辯、行賄欺官，終必敗露遭法網。切勿妄求財利，訴訟必凶，宜速和解，以免後悔。" },
      { title: "第五十七首 中平籤", poem: "事端百出廣雖長，莫聽人言自主張，一著仙機君記取，紛紛閒裏更思量。", explain: "世事紛亂，勿輕信人言，應有主見當機立斷。紛擾中更需冷靜思量，掌握關鍵契機。" },
      { title: "第五十八首 上吉籤", poem: "蘇秦三寸足平生，富貴功名在此行，更好修爲陰騭事，前程萬里自通亨。", explain: "憑口才與努力可得富貴，若能多積陰德，前程更是萬里通亨。功名、婚姻、疾病皆吉。" },
      { title: "第五十九首 中平籤", poem: "門衰戶冷苦伶仃，自嘆祈求不一靈，幸有祖宗陰德在，香烟未斷續蛾蛉。", explain: "家道雖中衰，幸祖德尚存，香火未斷。不可自暴自棄，努力奮鬥仍有一線生機。" },
      { title: "第六十首 上上籤", poem: "羨君兄弟好名聲，只管謙偽莫自矜，丹詔槐黃相逼近，巍巍科甲兩同登。", explain: "兄弟同心且有好名聲，切記謙虛勿驕傲。科甲聯登，前程光明。謀事、財利、功名皆順。" },
      { title: "第六十一首 中平籤", poem: "嘯聚山林兇惡儔，善良無事苦煎憂，主人大笑出門去，不用干戈盜賊休。", explain: "小人侵擾令良善者憂，但有德者（貴人）談笑間即可化解，不需動武。先驚後吉，宜守善放鬆。" },
      { title: "第六十二首 中平籤", poem: "百千人面虎狼心，賴汝干戈用力深，得勝回時秋漸老，虎頭城裏喜相尋。", explain: "人心險惡如虎狼，須靠自己奮力爭取。勝利歸來已近秋末，險地逢喜。晚景轉好，宜忍耐奮鬥。" },
      { title: "第六十三首 中平籤", poem: "曩時敗北且圖南，筋力雖衰尚一堪，欲識生前君大數，前三三與後三三。", explain: "昔日失敗，今轉向圖謀。雖年長力衰尚可一搏。命數已定，晚年仍有作為，勿強求。" },
      { title: "第六十四首 上上籤", poem: "吉人相遇本和同，況有持籌天水翁，人力不勞公論協，事成功倍笑談中。", explain: "遇貴人相助，彼此志同道合，更有智者籌謀。不費氣力，談笑間事半功倍，大吉大利。" },
      { title: "第六十五首 上上籤", poem: "朔風凜凜正窮冬，多羨門庭喜氣濃，更入新春人事後，衷言方得信先容。", explain: "雖處嚴冬低谷，門庭已現喜氣。待新春人事轉好，真誠言語終得貴人接納。否極泰來，先苦後甜。" },
      { title: "第六十六首 上上籤", poem: "耕耘只可在鄉邦，何用求謀向外方，見說今年新運好，門欄喜氣事雙雙。", explain: "安分在家耕耘即可，何必外出奔波。今年運勢轉好，喜事連連。宜守成，外出不利。" },
      { title: "第六十七首 中平籤", poem: "才發君心天已知，何須問我決狐疑，願子改圖從孝悌，不愁家室不相宜。", explain: "起心動念天已知，何須問神。勸君改過自新，重孝悌，家室自然和順。行善改過，諸事皆宜。" },
      { title: "第六十八首 中平籤", poem: "南販珍珠北販鹽，年來幾倍貨財添，勸君止此求田舍，心欲多時何日厭。", explain: "經商獲利已豐，勸君知足，置產安居。貪念無止境，應適可而止。宜守成，勿再冒險貪求。" },
      { title: "第六十九首 下下籤", poem: "舍舟遵路總相宜，慎勿嬉遊逐貴兒，一夜樽前兄與弟，明朝仇敵又相隨。", explain: "捨舟走陸路較安。切勿貪玩攀附權貴，酒肉朋友翻臉無情，今日兄弟明日仇敵。交友務必謹慎。" },
      { title: "第七十首 中平籤", poem: "雷雨風雲各有司，至誠禱告莫生疑，與君定約為霖日，正是蘊隆中伏時。", explain: "萬事有定數，至誠祈禱勿疑。時機約在三伏天（最熱時），耐心等待，誠心自有靈應。" },
      { title: "第七十一首 中平籤", poem: "喜鵲簷前報好音，知君千里欲歸心，繡縫重結鴛鴦帶，葉落霜飛寒色侵。", explain: "秋冬之際喜鵲報音，遠方親人將歸。雖目前寒冷焦慮，但好運已近。重修舊好，耐心靜待轉機。" },
      { title: "第七十二首 下下籤", poem: "河渠傍路有高低，可歎長途日已西，縱有榮華好時節，直須猴犬換金雞。", explain: "路途崎嶇，日薄西山。縱有往日榮華，如今已是沒落。盛衰循環，時運已過，宜盡人事聽天命。" },
      { title: "第七十三首 下下籤", poem: "憶昔閨房分半釵，而今忽把信音乖，痴心指望成連理，到底誰知事不諧。", explain: "昔日山盟海誓，如今音訊全無。痴心指望終成空，事難圓滿。宜面對現實，莫再執著。" },
      { title: "第七十四首 上吉籤", poem: "崔巍崔巍復崔巍，履險如夷去復來，身似菩提心似鏡，長安一道放春回。", explain: "山高路險，卻能履險如夷平安歸來。只要心如明鏡、身似菩提，正氣浩然，必能逢凶化吉，前程似錦。" },
      { title: "第七十五首 中吉籤", poem: "生前結得好姻緣，一笑相逢情自親，相當人物無高下，得意休論富與貧。", explain: "前世結善緣，今生一見鍾情。只要人品相當，何必計較貧富。眼光放遠，可得圓滿佳偶。" },
      { title: "第七十六首 中平籤", poem: "三千法律八千丈，此事如何說與君，善惡兩途君自作，一生禍福此中分。", explain: "法律森嚴，善惡只在一念間。一生禍福皆由自招，種瓜得瓜。宜趨善避惡，切勿貪取強求。" },
      { title: "第七十七首 下下籤", poem: "木有根荄水有源，君當自此究其原，莫隨道路人閒話，訟則終凶是至言。", explain: "凡事追根究柢，勿聽信閒言。禍從口出，訴訟必凶。宜和解，防口舌是非，盡力醫治疾病。" },
      { title: "第七十八首 下下籤", poem: "家道豐腴自飽溫，也須肚裏立乾坤，財多害己君當省，福有胚胎禍有門。", explain: "家境富裕仍須有主見。財多易招禍害己，吉凶皆自招。不可妄求，宜積善去惡，防酒色生禍。" },
      { title: "第七十九首 中平籤", poem: "乾亥來龍仔細看，城居午向自當安，若移丑食陰陽逆，門戶凋零家道難。", explain: "凡事須循天理與正道（如風水定局）。若逆天而行，必致門戶凋零。按部就班，勿輕易改變現狀。" },
      { title: "第八十首 中平籤", poem: "一朝無事忽遭官，也是門衰墳未安，改換陰陽移禍福，勸君莫作等閒看。", explain: "平白招官司，恐因積德不足或風水不安。唯有改過遷善、多積陰德，方能移禍為福。" },
      { title: "第八十一首 中平籤", poem: "假君財物自當還，謀賴心欺他自奸，幸有高臺明月鏡，請來對照破機關。", explain: "借物當還，賴帳欺瞞必遭報應。幸有明鏡高懸（神明/法律），終將照破奸計，還人公道。" },
      { title: "第八十二首 上吉籤", poem: "彼亦儔中一輩賢，勸君特達與周旋，此時賓主歡相會，他日王侯卻並肩。", explain: "對方為賢良之輩，宜主動結交。此時歡聚，他日可並肩發達。貴人緣厚，前途無量。" },
      { title: "第八十三首 下下籤", poem: "隨分堂前與粥饘，何須妄想苦憂煎，主張門戶誠難事，百歲安間得幾年。", explain: "安分守己，隨遇而安，何必妄想貪求自尋煩惱。持家不易，人生苦短，宜守成，防小人暗箭。" },
      { title: "第八十四首 中平籤", poem: "箇中事緒與紛然，當局須知一着先，長舌婦人休酷聽，力行禮義要心堅。", explain: "事緒紛亂，須有先見之明與決斷。切勿輕信婦人長舌是非，堅守禮義與信心，方能成功。" },
      { title: "第八十五首 中平籤", poem: "一春風雨正蕭蕭，千里行人去路遙，移寡就多君得計，如向歸路轉無聊。", explain: "風雨蕭蕭，歸路遙遠。縱有巧計移花接木，終是無聊徒勞。切勿詐取，守舊為宜。" },
      { title: "第八十六首 上上籤", poem: "一舟行貨好招邀，積少成多自富饒，常把他人比自己，管須日後勝今朝。", explain: "貨物搶手，積少成多致富。若能推己及人、為他人設想，將來必定更發達。勿得意忘形。" },
      { title: "第八十七首 下下籤", poem: "陰裏詳看怪爾曹，舟中敵圖笑中刀，藩籬剖破渾無事，一種天生惜羽毛。", explain: "骨肉猜忌，笑裏藏刀。若能坦誠相見、拆除藩籬，自可平安無事。宜大公無私，愛惜羽毛。" },
      { title: "第八十八首 上吉籤", poem: "從前作事總徒勞，纔見新春時漸遭，百計營求都得意，更須守己莫心高。", explain: "往日徒勞，新春時運漸亨通。謀求皆得意，但須守己莫驕傲。榮華將至，勤加努力。" },
      { title: "第八十九首 中平籤", poem: "樽前無事且高歌，時未來時奈若何，白馬渡江嘶日暮，虎頭城裏看巍峨。", explain: "時運未到，不妨且放酒高歌，何必長吁短嘆。大器晚成，待晚景運轉，必有一番轟烈作為。" },
      { title: "第九十首 中平籤", poem: "崆峒城裏事如麻，無事如君有幾家，勸汝不須勤致禱，徒勞生事苦咨嘆。", explain: "世事如麻，能平安無事已是幸運。知足常樂，切勿妄求多事，反招禍患。守靜為宜。" },
      { title: "第九十一首 中平籤", poem: "佛說淘沙始見金，只緣君子不勞心，榮華總得詩書効，妙裏工夫仔細尋。", explain: "淘沙見金，不勞獲。富貴靠苦讀與磨練。天下無不勞而獲，歷盡艱辛，方有所成。" },
      { title: "第九十二首 下下籤", poem: "今年禾穀不如前，物價喧騰倍百年，災數流行多疫癘，一陽復後始安全。", explain: "收成不佳，物價飛漲，疫病流行。運途不吉，須忍耐待冬至（一陽來復）後，方能轉危為安。" },
      { title: "第九十三首 中平籤", poem: "春來雨水太連綿，入夏晴乾雨又愆，節氣直交三伏始，喜逢滂沛足田園。", explain: "春雨綿綿夏乾旱，氣候乖張。須待三伏天後，方逢甘霖。謀事宜先難後易，耐心等待時機。" },
      { title: "第九十四首 中平籤", poem: "一般器用與人同，巧斷輪輿梓匠工，凡事有緣且隨分，秋冬方遇主人翁。", explain: "人心皆同，但凡事講緣分。安分守己，切勿妄動。待秋冬之際，貴人相助，方能亨通。" },
      { title: "第九十五首 中平籤", poem: "知君袖內有驪珠，生不逢辰亦強圖，可歎頭顱已如許，而今方得貴人扶。", explain: "懷才不遇，強求無益。雖嘆年華已逝，幸晚年得貴人扶助，終能有所成就。藏器待時。" },
      { title: "第九十六首 上吉籤", poem: "婚姻子息莫嫌遲，但把精神仗佛持，四十年前須報應，功圓行滿音馨兒。", explain: "莫嫌姻緣子息遲，心地光明神必佑。平日樂善好施，終得善報。功德圓滿，喜獲麟兒。" },
      { title: "第九十七首 上上籤", poem: "五十功名心已灰，那知富貴逼人來，更行好事存方寸，壽比岡陵位鼎台。", explain: "年半百心已灰，不料富貴逼人來。多存善念行好事，必享高壽與高位。雖遲必貴。" },
      { title: "第九十八首 中平籤", poem: "經營百出費精神，南北奔馳運未新，玉兔交時當得意，恰如枯木再逢春。", explain: "經營奔波徒勞神，時運未到。待兔年/月/日（玉兔交時），枯木逢春，名利雙收。先凶後吉。" },
      { title: "第九十九首 上上籤", poem: "貴人遭遇水雲卿，冷淡交情滋味長，黃閣開時延故客，驊騮應得驟康莊。", explain: "早遇貴人雖交淡，情義卻長。時機一到，貴人提攜，如騎良馬奔康莊大道。飛黃騰達，百事吉。" },
